// Embed the app icon and version info into the Windows executable, so it shows
// in Explorer, the taskbar and "Installed apps".
fn main() {
    const ICON: &str = "assets/rnnoise-mic.ico";
    println!("cargo:rerun-if-changed={ICON}");
    // The icon is generated by `cargo run --example make_icon`, which itself needs
    // this build script to succeed first.
    #[cfg(windows)]
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") && std::path::Path::new(ICON).exists() {
        let mut res = winresource::WindowsResource::new();
        res.set_icon(ICON)
            .set("ProductName", "RNNoise Mic")
            .set("FileDescription", "RNNoise Mic - system-wide microphone noise suppression");
        res.compile().expect("failed to embed Windows resources");
    }
}
